def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[i][j] == 2 for i in (r, r + 1) for j in (c, c + 1)):
                blocks.append((r, c))

    for r, c in blocks:
        clues = {}
        for rr in range(h):
            for cc in range(w):
                color = grid[rr][cc]
                if color in (3, 6, 7, 8) and (rr, cc) not in (
                    (r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)
                ):
                    if abs(rr - r) <= 2 and abs(cc - c) <= 2:
                        quadrant = (0 if rr < r else 1, 0 if cc < c else 1)
                        clues[quadrant] = color

        # Each surrounding clue paints a diagonal outward from its corresponding
        # corner of the 2x2 block.
        rays = [
            ((r, c), -1, -1, (1, 0)),       # upper-left corner, up-left
            ((r, c + 1), -1, 1, (0, 1)),   # upper-right corner, up-right
            ((r + 1, c), 1, -1, (1, 1)),   # lower-left corner, down-left
            ((r + 1, c + 1), 1, 1, (0, 0)) # lower-right corner, down-right
        ]
        # Map each clue quadrant to the ray shown by the examples.
        mapping = {
            (0, 0): ((r, c + 1), -1, 1),
            (0, 1): ((r + 1, c + 1), 1, 1),
            (1, 0): ((r, c), -1, -1),
            (1, 1): ((r + 1, c), 1, -1),
        }
        for q, color in clues.items():
            (sr, sc), dr, dc = mapping[q]
            rr, cc = sr, sc
            while 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] != 2:
                    out[rr][cc] = color
                rr += dr
                cc += dc
    return out
